class Solution {
public:
    long long minimumWeight(int n, vector<vector<int>>& edges, int src1, int src2, int dest) {
        const long long INF = (long long)1e18;

        vector<vector<pair<int,long long>>> fwd(n), rev(n);
        for (auto& e : edges) {
            fwd[e[0]].push_back({e[1], (long long)e[2]});
            rev[e[1]].push_back({e[0], (long long)e[2]});
        }

        auto dijkstra = [&](vector<vector<pair<int,long long>>>& g, int src) {
            vector<long long> dist(n, INF);
            priority_queue<pair<long long,int>, vector<pair<long long,int>>, greater<pair<long long,int>>> pq;
            dist[src] = 0;
            pq.push({0, src});
            while (!pq.empty()) {
                auto [d, u] = pq.top(); pq.pop();
                if (d > dist[u]) continue;
                for (auto& [v, w] : g[u]) {
                    if (dist[u] + w < dist[v]) {
                        dist[v] = dist[u] + w;
                        pq.push({dist[v], v});
                    }
                }
            }
            return dist;
        };

        vector<long long> da = dijkstra(fwd, src1);
        vector<long long> db = dijkstra(fwd, src2);
        vector<long long> dd = dijkstra(rev, dest);

        long long ans = INF;
        for (int x = 0; x < n; x++) {
            if (da[x] < INF && db[x] < INF && dd[x] < INF) {
                long long sum = da[x] + db[x] + dd[x];
                if (sum < ans) ans = sum;
            }
        }
        return ans >= INF ? -1 : ans;
    }
};
